$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-Log "Starting Visual C++ Runtimes Installation..."

$mediaRoot = Get-InstallMedia

function Install-Runtime {
    param(
        [string]$Url,
        [string]$DestName,
        [string]$LogName,
        [string]$LocalFolder
    )

    $setupPath = $null
    $dest = "$env:TEMP\$DestName"

    # 1. Try Download (Online First)
    if (Download-File -Url $Url -Destination $dest -Name $LogName) {
        $setupPath = $dest
    }

    # 2. Try Local (Fallback)
    if (-not $setupPath -and $mediaRoot) {
        Write-Log "Download of $LogName failed. Checking local storage..."
        $possiblePaths = @(
            (Join-Path $mediaRoot "apps\$LocalFolder"),
            (Join-Path $mediaRoot "drivers\apps\$LocalFolder"),
            (Join-Path $mediaRoot "Apps\$LocalFolder"),
            (Join-Path $mediaRoot "Drivers\Apps\$LocalFolder")
        )
        foreach ($path in $possiblePaths) {
             if (Test-Path $path) {
                 $localInstaller = Get-InstallerFile -Path $path
                 if ($localInstaller) {
                    $setupPath = $localInstaller
                    break
                 }
             }
        }
    }

    if ($setupPath) {
        Write-Log "Installing $LogName from $setupPath..."
        try {
            Unblock-File -Path $setupPath -ErrorAction SilentlyContinue
            Start-Process -FilePath $setupPath -ArgumentList @("/install", "/quiet", "/norestart") -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\${DestName}_install.log"
            Write-Log "$LogName installation completed."
        } catch {
            Write-Log "Error installing $LogName: $_"
        }
    } else {
        Write-Log "$LogName installer not found locally and download failed."
    }
}

# Official Microsoft Link for Latest Supported VC++ 2015-2022
$url64 = "https://aka.ms/vc14/vc_redist.x64.exe"
$url86 = "https://aka.ms/vc14/vc_redist.x86.exe"

Install-Runtime -Url $url64 -DestName "vc_redist.x64.exe" -LogName "Visual C++ Runtimes (x64)" -LocalFolder "vcredist_x64"
Install-Runtime -Url $url86 -DestName "vc_redist.x86.exe" -LogName "Visual C++ Runtimes (x86)" -LocalFolder "vcredist_x86"

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-Log "Starting Chrome Installation..."

# Check if Chrome is already installed
if ((Test-Path "$env:ProgramFiles\Google\Chrome\Application\chrome.exe") -or (Test-Path "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe")) {
    Write-Log "Chrome is already installed. Skipping."
    return
}

$mediaRoot = Get-InstallMedia
$setupPath = $null

# 1. Try Download (Online First) - Prefer Enterprise MSI
$url = 'https://dl.google.com/chrome/install/googlechromestandaloneenterprise64.msi'
$dest = "$env:TEMP\chrome.msi"
if (Download-File -Url $url -Destination $dest -Name "Chrome Enterprise MSI") {
    $setupPath = $dest
}

# 2. Try Local (Fallback)
if (-not $setupPath -and $mediaRoot) {
    Write-Log "Download failed. Checking local storage..."
    $possiblePaths = @(
        (Join-Path $mediaRoot "apps\chrome"),
        (Join-Path $mediaRoot "drivers\apps\chrome"),
        (Join-Path $mediaRoot "Apps"),
        (Join-Path $mediaRoot "Drivers\Apps")
    )
    foreach ($path in $possiblePaths) {
         if (Test-Path $path) {
             # Prioritize MSI, then EXE
             $localInstaller = Get-InstallerFile -Path $path -Extensions @("*.msi", "*.exe")
             if ($localInstaller) {
                $setupPath = $localInstaller
                break
             }
         }
    }
}

if ($setupPath) {
    Write-Log "Installing Chrome from $setupPath..."
    try {
        Unblock-File -Path $setupPath -ErrorAction SilentlyContinue

        if ($setupPath -match '\.msi$') {
            # MSI Installation
            # Note: msiexec requires strict quoting for paths with spaces
            $msiArgs = @("/i", "$setupPath", "/qn", "/norestart")
            Start-Process -FilePath "msiexec.exe" -ArgumentList $msiArgs -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\chrome_install.log"
        } else {
            # EXE Installation
            Start-Process -FilePath $setupPath -ArgumentList @('/silent', '/install') -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\chrome_install.log"
        }

        # Cleanup temp file
        if ($setupPath -match "$env:TEMP\\chrome\.(msi|exe)") {
            Remove-Item -Path $setupPath -Force -ErrorAction SilentlyContinue
        }
        Write-Log "Chrome installation completed."
    } catch {
        Write-Log "Error installing Chrome: $_"
    }
} else {
    Write-Log "Chrome installer not found locally and download failed."
}

$ErrorActionPreference = 'Stop' . "$PSScriptRoot\Lib\Helper.ps1"
$packagesToRemove = @( 'Microsoft.Microsoft3DViewer', 'Microsoft.BingSearch', 'Microsoft.WindowsCamera', 'Clipchamp.Clipchamp', 'Microsoft.WindowsAlarms', 'Microsoft.549981C3F5F10', # Cortana 'Microsoft.Copilot', 'Microsoft.Windows.DevHome', 'MicrosoftCorporationII.MicrosoftFamily', 'Microsoft.WindowsFeedbackHub', 'Microsoft.GetHelp', 'Microsoft.Getstarted', 'microsoft.windowscommunicationsapps', 'Microsoft.WindowsMaps', 'Microsoft.MixedReality.Portal', 'Microsoft.BingNews', 'Microsoft.MicrosoftOfficeHub', 'Microsoft.Office.OneNote', 'Microsoft.OutlookForWindows', 'Microsoft.People', 'Microsoft.Windows.PeopleExperienceHost', 'Microsoft.Windows.Photos', 'Microsoft.PowerAutomateDesktop', 'MicrosoftCorporationII.QuickAssist', 'Microsoft.SkypeApp', 'Microsoft.MicrosoftSolitaireCollection', 'Microsoft.MicrosoftStickyNotes', 'MicrosoftTeams', 'MSTeams', 'Microsoft.Todos', 'Microsoft.WindowsSoundRecorder', 'Microsoft.Wallet', 'Microsoft.BingWeather', 'Microsoft.ZuneVideo', 'MicrosoftWindows.Client.WebExperience', 'Microsoft.Windows.Ai.Copilot.Provider', 'Microsoft.YourPhone', 'Microsoft.GamingApp', 'Microsoft.XboxGameOverlay', 'Microsoft.XboxGamingOverlay', 'Microsoft.XboxIdentityProvider', 'Microsoft.XboxSpeechToTextOverlay', 'Microsoft.Windows.ParentalControls' )
$capabilitiesToRemove = @( 'Print.Fax.Scan', 'Browser.InternetExplorer', 'MathRecognizer', 'OneCoreUAP.OneSync', 'App.Support.QuickAssist', 'App.StepsRecorder', 'Hello.Face', 'Media.WindowsMediaPlayer', 'Microsoft.Windows.WordPad' )
$featuresToRemove = @( 'MediaPlayback', 'Microsoft-RemoteDesktopConnection', 'Recall' )
Write-Log "Starting Debloating Process..."
# Remove Appx Provisioned Packages $provisioned = Get-AppxProvisionedPackage -Online foreach ($package in $packagesToRemove) { $found = $provisioned | Where-Object { $_.DisplayName -eq $package } if ($found) { foreach ($item in $found) { Write-Log "Removing $($item.DisplayName) ($($item.PackageName))..." try { Remove-AppxProvisionedPackage -Online -PackageName $item.PackageName -ErrorAction Continue | Out-Null } catch { Write-Log "Failed to remove $($item.PackageName): $_" } } } }
# Remove Capabilities $capabilities = Get-WindowsCapability -Online foreach ($capName in $capabilitiesToRemove) { $cap = $capabilities | Where-Object { ($_.Name -split '~')[0] -eq $capName -and $_.State -ne 'NotPresent' } if ($cap) { Write-Log "Removing capability $capName..." try { Remove-WindowsCapability -Online -Name $cap.Name -ErrorAction Continue | Out-Null } catch { Write-Log "Failed to remove capability $capName: $_" } } }
# Remove Optional Features foreach ($feature in $featuresToRemove) { if ((Get-WindowsOptionalFeature -Online -FeatureName $feature -ErrorAction SilentlyContinue).State -eq 'Enabled') { Write-Log "Disabling feature $feature..." try { Disable-WindowsOptionalFeature -Online -FeatureName $feature -Remove -NoRestart -ErrorAction Continue | Out-Null } catch { Write-Log "Failed to disable feature $feature: $_" } } }
Write-Log "Debloating Process Completed."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-Log "Applying System Optimizations..."

# 1. Disable Hibernation (Saves disk space)
try {
    powercfg -h off
    Write-Log "Hibernation disabled."
} catch {
    Write-Log "Failed to disable hibernation: $_"
}

# 2. Set High Performance Power Plan
try {
    powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c
    Write-Log "Power plan set to High Performance."
} catch {
    Write-Log "Failed to set power plan: $_"
}

# 3. Disable Game DVR (Background recording)
reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\GameDVR" /v AllowGameDVR /t REG_DWORD /d 0 /f

# 4. Disable Last Access Timestamp (Reduces disk I/O)
try {
    fsutil behavior set disablelastaccess 1
    Write-Log "Last Access Timestamp disabled."
} catch {
    Write-Log "Failed to disable Last Access Timestamp: $_"
}

Write-Log "System Optimizations Applied."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

$scripts = @(
    "$PSScriptRoot\Drivers\Install-Network.ps1",
    "$PSScriptRoot\Tweaks\Remove-Bloatware.ps1",
    "$PSScriptRoot\Tweaks\Configure-Privacy.ps1",
    "$PSScriptRoot\Tweaks\Optimize-System.ps1",
    "$PSScriptRoot\Drivers\Install-Nvidia.ps1",
    "$PSScriptRoot\Drivers\Install-AMD.ps1",
    "$PSScriptRoot\Drivers\Install-Focusrite.ps1",
    "$PSScriptRoot\Apps\Install-Runtimes.ps1",
    "$PSScriptRoot\Apps\Install-Chrome.ps1",
    "$PSScriptRoot\Tweaks\SetStartPins.ps1"
)

Write-Log "Starting Specialize Pass (Optimized)..."

foreach ($script in $scripts) {
    if (Test-Path $script) {
        Write-Log "Executing $script..."
        try {
            & $script
        } catch {
            Write-Log "Error executing $script: $_"
        }
    } else {
        Write-Log "Script not found: $script"
    }
}

# Generate SetupComplete.cmd for post-OOBE cleanup
# This ensures unattend.xml is removed to prevent sensitive data leak (if any)
# We do NOT remove the Scripts folder here because UserOnce.ps1 (RunOnce) needs it.
$setupCompleteContent = @"
del /q /f "%WINDIR%\Panther\unattend.xml"
del /q /f "%WINDIR%\Panther\unattend-original.xml"
"@

$setupCompletePath = "$env:SystemRoot\Setup\Scripts\SetupComplete.cmd"
try {
    $setupDir = Split-Path -Path $setupCompletePath -Parent
    if (-not (Test-Path $setupDir)) {
        New-Item -Path $setupDir -ItemType Directory -Force | Out-Null
    }
    Set-Content -Path $setupCompletePath -Value $setupCompleteContent -Force
    Write-Log "Generated SetupComplete.cmd for cleanup."
} catch {
    Write-Log "Error creating SetupComplete.cmd: $_"
}

Write-Log "Specialize Pass Completed."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-Log "Configuring Default User..."

# Load Default User Hive
$defaultUserHive = "HKU\DefaultUser"
$weLoadedIt = $false

# Robustly load hive: Check if already loaded first
if (-not (Test-Path "Registry::$defaultUserHive")) {
    Write-Log "Loading Default User hive..."
    try {
        $result = reg.exe load $defaultUserHive "C:\Users\Default\NTUSER.DAT" 2>&1
        if ($LASTEXITCODE -eq 0) {
            $weLoadedIt = $true
        } else {
            Write-Log "Failed to load Default User hive: $result"
            return
        }
    } catch {
        Write-Log "Exception loading Default User hive: $_"
        return
    }
} else {
    Write-Log "Default User hive already loaded."
}

try {
    # Taskbar and Explorer settings
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v ShowTaskViewButton /t REG_DWORD /d 0 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarAl /t REG_DWORD /d 0 /f # Left align taskbar
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v LaunchTo /t REG_DWORD /d 1 /f # Open This PC
    reg.exe add "$defaultUserHive\Software\Policies\Microsoft\Windows\Explorer" /v DisableSearchBoxSuggestions /t REG_DWORD /d 1 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Search" /v SearchboxTaskbarMode /t REG_DWORD /d 3 /f # Icon only

    # Show File Extensions
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v HideFileExt /t REG_DWORD /d 0 /f

    # Show "This PC" Icon on Desktop
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" /v "{20D04FE0-3AEA-1069-A2D8-08002B30309D}" /t REG_DWORD /d 0 /f

    # Disable Sync Provider Notifications (Ads in File Explorer)
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v ShowSyncProviderNotifications /t REG_DWORD /d 0 /f

    # Enable Dark Mode (System and Apps)
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" /v AppsUseLightTheme /t REG_DWORD /d 0 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" /v SystemUsesLightTheme /t REG_DWORD /d 0 /f

    # Classic Context Menu (Windows 11)
    reg.exe add "$defaultUserHive\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32" /ve /t REG_SZ /d "" /f

    # Disable Lock Screen Tips, Tips and Suggestions, and Welcome Experience
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v RotatingLockScreenEnabled /t REG_DWORD /d 0 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-338387Enabled /t REG_DWORD /d 0 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SoftLandingEnabled /t REG_DWORD /d 0 /f
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-310093Enabled /t REG_DWORD /d 0 /f

    # Disable Copilot for Default User
    reg.exe add "$defaultUserHive\Software\Policies\Microsoft\Windows\WindowsCopilot" /v TurnOffWindowsCopilot /t REG_DWORD /d 1 /f

    # Enable End Task in Taskbar (Developer/Power User feature)
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarEndTask /t REG_DWORD /d 1 /f

    # Disable "Finish setting up your device"
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement" /v ScoobeSystemSettingEnabled /t REG_DWORD /d 0 /f

    # Run UserOnce on first login (if script exists)
    # We wrap in cmd /c "if exist ..." to prevent errors for subsequent users after self-destruct
    $uScript = "C:\Windows\Setup\Scripts\UserOnce.ps1"
    $runOnceCmd = "cmd /c `"if exist \`"$uScript\`" powershell.exe -WindowStyle Normal -ExecutionPolicy Unrestricted -NoProfile -File \`"$uScript\`"`""
    reg.exe add "$defaultUserHive\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d $runOnceCmd /f
}
catch {
    Write-Log "Error applying Default User tweaks: $_"
}
finally {
    # Only unload if we loaded it to avoid disrupting other processes
    if ($weLoadedIt) {
        Write-Log "Unloading Default User hive..."
        [GC]::Collect() # Force GC to release handles

        $maxRetries = 5
        $retry = 0
        $unloaded = $false

        while (-not $unloaded -and $retry -lt $maxRetries) {
            try {
                $result = reg.exe unload $defaultUserHive 2>&1
                if ($LASTEXITCODE -eq 0) {
                    $unloaded = $true
                    Write-Log "Default User hive unloaded successfully."
                } else {
                    Write-Log "Failed to unload Default User hive (Attempt $($retry+1)): $result"
                    Start-Sleep -Seconds 2
                    [GC]::Collect()
                    $retry++
                }
            } catch {
                Write-Log "Exception unloading Default User hive (Attempt $($retry+1)): $_"
                Start-Sleep -Seconds 2
                $retry++
            }
        }

        if (-not $unloaded) {
            Write-Log "CRITICAL: Could not unload Default User hive after $maxRetries attempts."
        }
    }
}

Write-Log "Default User Configuration Completed."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-Log "Configuring User Account..."

# Register Daily Winget Auto-Update Task (Transparent)
if (Get-Command winget -ErrorAction SilentlyContinue) {
    $taskName = "DailySoftwareUpdate"
    $wingetCmd = "winget source update; winget upgrade --all --include-unknown --silent --disable-interactivity --accept-source-agreements --accept-package-agreements"
    $action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-WindowStyle Hidden -Command `\"$wingetCmd`\""
    $trigger = New-ScheduledTaskTrigger -Daily -At 13:00
    # Attempt 1: Try with Highest RunLevel (Admin)
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -Hidden -RunOnlyIfNetworkAvailable

    $registered = $false
    try {
        Write-Log "Attempting to register Winget task with Highest privileges..."
        Register-ScheduledTask -Action $action -Trigger $trigger -Settings $settings -TaskName $taskName -Description "Automatically updates all software via Winget silently." -RunLevel Highest -Force -ErrorAction Stop | Out-Null
        $registered = $true
        Write-Log "Registered Daily Winget Auto-Update Task (Highest)."
    } catch {
        Write-Log "Failed to register Winget task with Highest privileges: $_"
    }

    # Attempt 2: Try with Limited (User) privileges if Admin failed (e.g., UAC issue)
    if (-not $registered) {
        try {
            Write-Log "Attempting to register Winget task with Limited privileges..."
            Register-ScheduledTask -Action $action -Trigger $trigger -Settings $settings -TaskName $taskName -Description "Automatically updates all software via Winget silently." -RunLevel Limited -Force -ErrorAction Stop | Out-Null
            $registered = $true
            Write-Log "Registered Daily Winget Auto-Update Task (Limited)."
        } catch {
            Write-Log "Failed to register Winget task (Limited): $_"
        }
    }
} else {
    Write-Log "Winget not found. Skipping auto-update task registration."
}

Write-Log "User Configuration Completed."

# Self-Destruct: Cleanup Scripts
# Wait 5 seconds then delete the script folder
Start-Process -FilePath "cmd.exe" -ArgumentList "/c timeout /t 5 /nobreak > NUL & rmdir /s /q `"$env:SystemRoot\Setup\Scripts`"" -WindowStyle Hidden
